class Solution:
    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        nums.sort();out=[];path=[]
        def dfs(start):
            out.append(path.copy())
            for i in range(start,len(nums)):
                if i>start and nums[i]==nums[i-1]:continue
                path.append(nums[i]);dfs(i+1);path.pop()
        dfs(0);return out

import java.util.*;

class Solution {
    public List<List<Integer>> subsetsWithDup(int[] nums){Arrays.sort(nums);List<List<Integer>>out=new ArrayList<>();dfs(nums,0,new ArrayList<>(),out);return out;}
    private void dfs(int[]a,int start,List<Integer>p,List<List<Integer>>out){out.add(new ArrayList<>(p));for(int i=start;i<a.length;i++){if(i>start&&a[i]==a[i-1])continue;p.add(a[i]);dfs(a,i+1,p,out);p.remove(p.size()-1);}}
}
